fn sdf__norm(_arg0: vec3&lt;f32&gt;) -&gt; f32 {
    let _v0: f32 = 0.000000;
    let _v1: vec3&lt;f32&gt; = _arg0 * _arg0;
    let _v2: f32 = _v0 + dot(_v1, vec3&lt;f32&gt;(1.0, 1.0, 1.0));
